parts.text:
{
  "thinking": "A_05와 A_06에게 E_04를 대상으로 스킬을 사용하도록 명령을 수행합니다.",
  "dialog": [
    {
      "unitId": "A_05",
      "text": "화염 폭풍으로 E_04를 불태우겠습니다."
    },
    {
      "unitId": "A_06",
      "text": "벼락을 떨어뜨려 E_04를 타격하겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_05",
      "sequence": [
        {
          "type": "skill",
          "description": "화염 폭풍을 일으켜 지정 범위 내 적들에게 마법 피해를 줍니다.",
          "target": "E_04"
        }
      ]
    },
    {
      "unitId": "A_06",
      "sequence": [
        {
          "type": "skill",
          "description": "벼락을 떨어뜨려 지정 범위 내 적들에게 큰 피해를 줍니다.",
          "target": "E_04"
        }
      ]
    }
  ]
}

{
  "thinking": "가장 체력이 낮은 타게팅 가능한 적 E_03을 집중 공격하도록 모든 아군에게 명령합니다.",
  "dialog": [
    {"unitId": "A_01", "text": "가장 약한 적부터 처치한다."},
    {"unitId": "A_02", "text": "집중 공격을 시작한다."},
    {"unitId": "A_03", "text": "공격에 집중하겠다."},
    {"unitId": "A_04", "text": "약점을 노려 사격한다."},
    {"unitId": "A_06", "text": "배후를 노려 공격하겠다."}
  ],
  "action": [
    {
      "unitId": "A_01",
      "sequence": [
        {"type": "move", "subtype": "approachOpponent", "movementType": "direct", "to": "E_03"},
        {"type": "attack", "target": "E_03"}
      ]
    },
    {
      "unitId": "A_02",
      "sequence": [
        {"type": "skill", "description": "검풍을 날려 전방의 적들을 공격합니다.", "target": "E_03"},
        {"type": "attack", "target": "E_03"}
      ]
    },
    {
      "unitId": "A_03",
      "sequence": [
        {"type": "attack", "target": "E_03"}
      ]
    },
    {
      "unitId": "A_04",
      "sequence": [
        {"type": "attack", "target": "E_03"}
      ]
    },
    {
      "unitId": "A_06",
      "sequence": [
        {"type": "move", "subtype": "approachOpponent", "movementType": "flank", "to": "E_03"},
        {"type": "attack", "target": "E_03"}
      ]
    }
  ]
}

{
  "thinking": "원거리 공격수인 A_05와 A_06에게 적 후방 부대인 E_06을 집중 공격하도록 명령합니다.",
  "dialog": [
    {
      "unitId": "A_05",
      "text": "후방의 적을 정밀 타격하겠습니다."
    },
    {
      "unitId": "A_06",
      "text": "적의 후방부터 무너뜨리겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_05",
      "sequence": [
        {
          "type": "attack",
          "target": "E_06"
        }
      ]
    },
    {
      "unitId": "A_06",
      "sequence": [
        {
          "type": "attack",
          "target": "E_06"
        }
      ]
    }
  ]
}

{
  "thinking": "A_04에게 A_05를 대상으로 스킬을 사용하라는 명령을 받았으나, A_04의 스킬은 자기 자신에게만 적용되는 스킬이므로 명령을 수행할 수 없습니다.",
  "dialog": [
    {
      "unitId": "A_04",
      "text": "제 스킬은 저 자신에게만 사용할 수 있습니다."
    }
  ],
  "action": []
}

{
  "thinking": "A_05가 쓰러진 A_03에게 접근하여 보호하라는 명령을 수행합니다.",
  "dialog": [
    {
      "unitId": "A_05",
      "text": "쓰러진 아군을 보호하기 위해 이동합니다."
    }
  ],
  "action": [
    {
      "unitId": "A_05",
      "sequence": [
        {
          "type": "move",
          "subtype": "help",
          "movementType": "direct",
          "to": "A_03"
        }
      ]
    }
  ]
}

{
  "thinking": "모든 아군 유닛의 skillDescription이 비어 있어 스킬을 사용할 수 있는 유닛이 없습니다.",
  "dialog": [],
  "action": []
}

{
  "thinking": "A_04에게 E_01을 타격하라는 명령을 수행하기 위해, A_04가 E_01에게 접근한 뒤 공격하도록 설정합니다.",
  "dialog": [
    {
      "unitId": "A_04",
      "text": "E_01을 타격하겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_04",
      "sequence": [
        {
          "type": "move",
          "subtype": "approachOpponent",
          "movementType": "direct",
          "to": "E_01"
        },
        {
          "type": "attack",
          "target": "E_01"
        }
      ]
    }
  ]
}

{
  "thinking": "A_02와 A_03에게 스킬 사용을 지연하도록 명령함.",
  "dialog": [
    {
      "unitId": "A_02",
      "text": "스킬은 잠시 아껴두겠습니다."
    },
    {
      "unitId": "A_03",
      "text": "알겠습니다, 스킬 사용을 미루겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_02",
      "sequence": [
        {
          "type": "skillControl",
          "mode": "defer",
          "durationSec": 5
        }
      ]
    },
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "skillControl",
          "mode": "defer",
          "durationSec": 5
        }
      ]
    }
  ]
}

{
  "thinking": "가장 체력이 낮은 적 E_05를 대상으로 스킬 사용이 가능한 아군들이 스킬을 사용하도록 명령을 수행합니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "번개 화살로 가장 약한 적을 노리겠다."
    },
    {
      "unitId": "A_04",
      "text": "정밀 사격으로 적의 숨통을 끊겠다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "skill",
          "description": "번개 화살을 쏘아 적 하나에게 큰 피해를 줍니다.",
          "target": "E_05"
        }
      ]
    },
    {
      "unitId": "A_04",
      "sequence": [
        {
          "type": "skill",
          "description": "정밀 사격으로 적 하나에게 치명적인 피해를 입힙니다.",
          "target": "E_05"
        }
      ]
    }
  ]
}

{
  "thinking": "A_03과 A_04에게 스킬 사용을 금지하고 아끼도록 지시함.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "마법 화살은 아껴두겠습니다."
    },
    {
      "unitId": "A_04",
      "text": "지진은 나중에 사용하겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "skillControl",
          "mode": "forbid"
        }
      ]
    },
    {
      "unitId": "A_04",
      "sequence": [
        {
          "type": "skillControl",
          "mode": "forbid"
        }
      ]
    }
  ]
}

{
  "thinking": "A_03과 A_04에게 스킬 사용 보류 명령을 수행하기 위해 skillControl을 적용합니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "마법 화살은 잠시 아껴두겠습니다."
    },
    {
      "unitId": "A_04",
      "text": "지진 마법은 보류하겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "skillControl",
          "mode": "defer",
          "durationSec": 5
        }
      ]
    },
    {
      "unitId": "A_04",
      "sequence": [
        {
          "type": "skillControl",
          "mode": "defer",
          "durationSec": 5
        }
      ]
    }
  ]
}

{
  "thinking": "A_03 유닛은 스킬 설명이 비어있어 스킬을 사용할 수 없으므로, 명령을 수행할 수 없습니다.",
  "dialog": [],
  "action": []
}

{
  "thinking": "A_05는 전방의 적 E_02를 저지하고, A_02는 후방의 적 E_06을 공격하도록 명령을 수행한다.",
  "dialog": [
    {
      "unitId": "A_05",
      "text": "전방의 적을 막아내겠다."
    },
    {
      "unitId": "A_02",
      "text": "후방의 적을 끊어내겠다."
    }
  ],
  "action": [
    {
      "unitId": "A_05",
      "sequence": [
        {
          "type": "move",
          "subtype": "approachOpponent",
          "movementType": "direct",
          "to": "E_02"
        },
        {
          "type": "attack",
          "target": "E_02"
        }
      ]
    },
    {
      "unitId": "A_02",
      "sequence": [
        {
          "type": "attack",
          "target": "E_06"
        }
      ]
    }
  ]
}

{
  "thinking": "교전 중이지 않은 아군(A_03, A_05, A_06)이 공격받는 아군(A_01, A_02, A_04)을 노리는 적(E_02, E_01, E_03)을 집중 타격하도록 명령을 수행합니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "가장 위협적인 적을 조준합니다."
    },
    {
      "unitId": "A_05",
      "text": "메테오로 적들을 일제히 타격하겠습니다."
    },
    {
      "unitId": "A_06",
      "text": "아군 공격력을 강화하고 적을 공격합니다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "attack",
          "target": "E_02"
        }
      ]
    },
    {
      "unitId": "A_05",
      "sequence": [
        {
          "type": "skill",
          "description": "하늘에서 메테오를 떨어뜨려 넓은 범위에 마법 피해를 줍니다.",
          "target": "E_02"
        }
      ]
    },
    {
      "unitId": "A_06",
      "sequence": [
        {
          "type": "skill",
          "description": "모든 아군의 공격력을 잠시 동안 상승시킵니다.",
          "target": "A_06"
        },
        {
          "type": "attack",
          "target": "E_01"
        }
      ]
    }
  ]
}

{
  "thinking": "A_03에게 E_02를 대상으로 스킬 사용을 지시했으나, E_02는 현재 죽어있고 타게팅이 불가능하여 스킬을 사용할 수 없습니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "대상인 E_02가 이미 쓰러져 있어 스킬을 사용할 수 없습니다."
    }
  ],
  "action": []
}

{
  "thinking": "체력이 가장 낮은 적 E_02를 처치하기 위해 A_01이 접근하여 공격을 수행한다.",
  "dialog": [
    {
      "unitId": "A_01",
      "text": "체력이 바닥난 적을 확실하게 마무리하겠다."
    }
  ],
  "action": [
    {
      "unitId": "A_01",
      "sequence": [
        {
          "type": "move",
          "subtype": "approachOpponent",
          "movementType": "direct",
          "to": "E_02"
        },
        {
          "type": "attack",
          "target": "E_02"
        }
      ]
    }
  ]
}

{
  "thinking": "A_03에게 쓰러진 A_01을 지원하라는 명령을 수행하기 위해, A_01의 위치로 이동하여 보호를 시도한다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "쓰러진 A_01 곁으로 이동해 방어 태세를 갖추겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "move",
          "subtype": "help",
          "movementType": "direct",
          "to": "A_05"
        }
      ]
    }
  ]
}

{
  "thinking": "A_03 유닛의 스킬 정보를 확인한 결과, 스킬 설명이 비어 있어 스킬을 시전할 수 없습니다. 따라서 명령을 수행할 수 없음을 알립니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "죄송합니다, 현재 사용할 수 있는 스킬이 없습니다."
    }
  ],
  "action": []
}

{
  "thinking": "힐러인 A_03이 체력이 가장 낮은 아군 A_06에게 치유 스킬을 사용하도록 명령을 수행합니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "상처 입은 아군을 치유하겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "skill",
          "description": "치유의 빛을 내뿜어 아군의 상처를 치료한다.",
          "target": "A_06"
        }
      ]
    }
  ]
}

{
  "thinking": "원거리 아군인 A_03과 A_06에게 적 뒷선(E_04, E_06)을 공격하도록 명령합니다.",
  "dialog": [
    {
      "unitId": "A_03",
      "text": "후방의 적들을 화염으로 쓸어버리겠습니다."
    },
    {
      "unitId": "A_06",
      "text": "뒷선의 적들을 정밀 사격으로 제거하겠습니다."
    }
  ],
  "action": [
    {
      "unitId": "A_03",
      "sequence": [
        {
          "type": "move",
          "subtype": "approachOpponent",
          "movementType": "flank",
          "to": "E_06"
        },
        {
          "type": "skill",
          "description": "화염구를 던져 폭발 피해를 입힙니다.",
          "target": "E_06"
        }
      ]
    },
    {
      "unitId": "A_06",
      "sequence": [
        {
          "type": "move",
          "subtype": "approachOpponent",
          "movementType": "flank",
          "to": "E_04"
        },
        {
          "type": "attack",
          "target": "E_04"
        }
      ]
    }
  ]
}
